// ============================================
// 1. Get AI response
// ============================================

const aiOutput = $json.output ?? $json.message?.content ?? $json.content;

if (!aiOutput) {
  throw new Error('AI response is empty or missing.');
}


// ============================================
// 2. Clean Markdown code fences
// ============================================

const cleanedOutput = String(aiOutput)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();


// ============================================
// 3. Parse AI JSON
// ============================================

let data;

try {
  data = JSON.parse(cleanedOutput);
} catch (error) {
  throw new Error(`Invalid JSON returned by AI: ${error.message}`);
}


// ============================================
// 4. Get customer name directly from email
// ============================================

const customerName =
  $('invoiceEmail').item.json.from?.value?.[0]?.name ?? null;


// ============================================
// 5. Normalize confidence score
// ============================================

let confidenceScore = Number(
  data.validation?.confidenceScore ?? 0
);

// If AI returns 0.0–1.0 instead of 1–10
if (confidenceScore > 0 && confidenceScore <= 1) {
  confidenceScore = Math.round(confidenceScore * 10);
}


// ============================================
// 6. Get invoice information
// ============================================

const invoice = data.invoice ?? null;

let dueDate = invoice?.dueDate ?? null;
let invoiceDate = invoice?.invoiceDate ?? null;
const paymentTerms = invoice?.paymentTerms ?? null;


// ============================================
// 7. Calculate due date if necessary
// ============================================

// If AI provided a due date, use it.
// Otherwise, try to calculate it from payment terms.

if (!dueDate && invoiceDate && paymentTerms) {

  const match = String(paymentTerms).match(/\d+/);

  if (match) {
    const days = parseInt(match[0], 10);

    const date = new Date(`${invoiceDate}T00:00:00Z`);

    date.setUTCDate(date.getUTCDate() + days);

    dueDate = date.toISOString().split('T')[0];
  }
}


// ============================================
// 8. Calculate days until due
// ============================================

let daysUntilDue = null;

if (dueDate) {

  const today = new Date();
  const todayUTC = new Date(
    Date.UTC(
      today.getUTCFullYear(),
      today.getUTCMonth(),
      today.getUTCDate()
    )
  );

  const dueDateUTC = new Date(`${dueDate}T00:00:00Z`);

  const difference =
    dueDateUTC.getTime() - todayUTC.getTime();

  daysUntilDue = Math.ceil(
    difference / (1000 * 60 * 60 * 24)
  );
}


// ============================================
// 9. Determine invoice status
// ============================================

let status = null;

const isPaid = data.payment?.isPaid ?? false;

if (isPaid) {

  status = 'Paid';

} else if (daysUntilDue !== null) {

  if (daysUntilDue >= 0) {
    status = 'Upcoming';
  } else {
    status = 'Overdue';
  }
}


// ============================================
// 10. Return clean n8n item
// ============================================

return {
  json: {

    category: data.category
      ? String(data.category).charAt(0).toUpperCase() +
        String(data.category).slice(1).toLowerCase()
      : null,

    validation: {
      isValidInvoice:
        data.validation?.isValidInvoice ?? false,

      confidenceScore,

      confidenceLevel:
        data.validation?.confidenceLevel ?? null
    },

    invoice: invoice
      ? {
          invoiceNumber:
            invoice.invoiceNumber ?? null,

          vendorName:
            invoice.vendorName ?? null,

          customerName,

          description:
            invoice.description ?? null,

          amountDue:
            invoice.amountDue ?? null,

          currency:
            invoice.currency ?? null,

          invoiceDate,

          dueDate,

          paymentTerms,

          senderEmail:
            invoice.senderEmail ?? null,

          subject:
            invoice.subject ?? null
        }
      : null,

    payment: {
      isPaid
    },

    status: {
      value: status,
      daysUntilDue
    }
  }
};

